import * as THREE from './vendor/three.module.js';
import {floorHeight,groundHeight,wetness} from './landscape.js?v=9';
export class Roadworks{
constructor(v){this.v=v;this.group=new THREE.Group();v.scene.add(this.group);this.lamps=[];}
clear(){this.group.traverse(o=>{if(o.geometry&&o.geometry!==this.v.unitBox)o.geometry.dispose()});this.group.clear();this.lamps=[]}
height(w,x,z){return Math.max(.32,floorHeight(w,x,z))+.1+wetness(w,x,z)*1.2}
ribbon(w,points,width,offset,material,raise=.03){const vertices=[],uv=[],indices=[];for(let i=0;i<points.length;i++){const p=points[i],a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz)||1,nx=-dz/len,nz=dx/len;for(let side of [-1,1]){const dist=offset+side*width*.5,x=p.x+nx*dist,z=p.z+nz*dist;vertices.push(x,this.height(w,x,z)+raise,z);uv.push(side===1?1:0,i/(points.length-1)*2)}if(i<points.length-1){let q=i*2;indices.push(q,q+1,q+2,q+1,q+3,q+2)}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();let m=new THREE.Mesh(geo,material);m.receiveShadow=true;this.group.add(m);return m}
line(w,points,width=.025,color='#e2ded0',offset=0){return this.ribbon(w,points,width,offset,this.v.mat(color),.065)}
build(w){this.clear();this.world=w;const asphalt=this.v.landscape.material('asphalt',.7,'#9b9f9c'),walk=this.v.mat('#767b73'),curb=this.v.mat('#92968c');const roads=w.tiles.map((t,i)=>t.type==='road'?i:-1).filter(i=>i>=0);
for(let i of roads){if(w.tiles[i].pathIds?.length&&!w.tiles[i].legacyRoad)continue;const x=(i%48+.5)*4-96,z=(Math.floor(i/48)+.5)*4-96,t=w.tiles[i],near=CityEngine.neighbors(i).filter(n=>w.tiles[n].type==='road'),dirs=near.map(n=>({x:(n%48-i%48),z:(Math.floor(n/48)-Math.floor(i/48))})),wide=t.roadWidth===2,width=wide?3.15:2.45;let points=[];
if(dirs.length===2&&dirs[0].x*dirs[1].x+dirs[0].z*dirs[1].z===0){const a=new THREE.Vector3(x+dirs[0].x*2,0,z+dirs[0].z*2),b=new THREE.Vector3(x+dirs[1].x*2,0,z+dirs[1].z*2);for(let s=0;s<=12;s++){const f=s/12,q=1-f;points.push({x:q*q*a.x+2*q*f*x+f*f*b.x,z:q*q*a.z+2*q*f*z+f*f*b.z})}}
else if(dirs.length<=2){let d=dirs.find(p=>p.x!==0)||dirs[0]||{x:1,z:0};const horizontal=d.x!==0;for(let j=0;j<=4;j++)points.push({x:x+(horizontal?j-2:0),z:z+(horizontal?0:j-2)})}
if(points.length){this.ribbon(w,points,width+.85,0,walk,0);this.ribbon(w,points,width,0,asphalt,.025);for(let s of [-1,1])this.ribbon(w,points,.065,s*(width/2+.035),curb,.075);for(let j=0;j<points.length-1;j+=2){this.line(w,[points[j],points[Math.min(j+1,points.length-1)]],.025,'#bcb9a4',0)}if(wide){for(let side of [-1,1])for(let j=0;j<points.length-1;j+=2)this.line(w,[points[j],points[j+1]],.023,'#cfcec0',side*.77)}}
else{const axis=[{x:x-2,z},{x:x+2,z}];this.ribbon(w,axis,3.75,0,walk,0);this.junction(w,x,z,width,asphalt,curb,dirs);for(let d of dirs){this.ribbon(w,[{x,z},{x:x+d.x*2,z:z+d.z*2}],width,0,asphalt,.04);for(let k=0;k<6;k++){const across=-width*.38+k*width*.15,side={x:-d.z,z:d.x};const p={x:x+d.x*1.72+side.x*across,z:z+d.z*1.72+side.z*across};this.line(w,[{x:p.x-d.x*.18,z:p.z-d.z*.18},{x:p.x+d.x*.18,z:p.z+d.z*.18}],.095,'#c7c5b6')}}}
if(t.ground==='water'){const y=this.height(w,x,z);this.v.box(this.group,x,y-.35,z,4,.55,wide?3.6:3.1,'#8b9491');let vertical=dirs.some(d=>d.z)&&!dirs.some(d=>d.x);for(let side of [-1,1]){this.v.box(this.group,x+(vertical?side*1.7:0),y+.45,z+(vertical?0:side*1.7),vertical?.06:4,.08,vertical?4:.06,'#a3a8a2');for(let a of [-1.5,0,1.5])this.v.box(this.group,x+(vertical?side*1.7:a),y+.22,z+(vertical?a:side*1.7),.05,.5,.05,'#a3a8a2')}if(i%2===0){this.v.box(this.group,x,y/2-1,z,.55,y+2,.65,'#9a9a8f')}}
if(dirs.length>=3&&i%2===0){this.signal(x+1.66,this.height(w,x,z),z+1.66)}
if(i%5===0&&t.ground!=='water'){let horizontal=dirs.some(d=>d.x),lx=x+(horizontal?0:1.8),lz=z+(horizontal?1.8:0),y=this.height(w,lx,lz);this.lamp(lx,y,lz,horizontal)}
}
for(const path of w.roadPaths||[])this.path(w,path,asphalt,walk,curb);
const out=[{x:-140,z:2},{x:-96,z:2}];this.ribbon(w,out,3.4,0,asphalt);this.line(w,out,.03,'#dbd5b4');}
path(w,path,asphalt,walk,curb){const spec=CityEngine.ROADS[path.type],points=CityEngine.sampleRoad(path.controls).map(p=>({x:(p.x+.5)*4-96,z:(p.y+.5)*4-96})),width=spec.width;this.ribbon(w,points,width+(spec.sidewalk?.7:.35),0,spec.sidewalk?walk:this.v.mat('#9a9784'),.1);this.ribbon(w,points,width,0,path.type==='gravel'?this.v.mat('#928875'):asphalt,.13);for(const side of [-1,1])this.ribbon(w,points,.045,side*(width/2-.09),spec.sidewalk?curb:this.v.mat('#c9c7b6'),.17);
if(spec.median)this.ribbon(w,points,.18,0,curb,.18);for(let lane=1;lane<spec.lanes;lane++){if(spec.median&&lane===spec.lanes/2)continue;for(let j=0;j<points.length-2;j+=7)this.ribbon(w,points.slice(j,Math.min(j+4,points.length)),.025,-width/2+lane*width/spec.lanes,this.v.mat(lane===spec.lanes/2&&!spec.oneway?'#c6bd98':'#d6d3c4'),.18)}
for(let j=4;j<points.length-1;j+=35){const p=points[j],a=points[j-1],b=points[j+1],dx=b.x-a.x,dz=b.z-a.z,l=Math.hypot(dx,dz)||1;if(spec.sidewalk)this.lamp(p.x-dz/l*(width/2+.25),this.height(w,p.x,p.z),p.z+dx/l*(width/2+.25),Math.abs(dx)>Math.abs(dz));if(wetness(w,p.x,p.z)>.3){this.v.box(this.group,p.x,this.height(w,p.x,p.z)/2-1,p.z,.4,this.height(w,p.x,p.z)+2,.4,'#9a9a8f')}if(spec.oneway){const dir={x:dx/l,z:dz/l};for(const side of [-1,1])this.line(w,[{x:p.x-dir.x*.4-dir.z*side*.22,z:p.z-dir.z*.4+dir.x*side*.22},p],.07,'#dedbc9')}if(spec.green){const tree=new THREE.Mesh(new THREE.SphereGeometry(.55,10,8),this.v.mat('#61754b'));tree.scale.y=1.4;tree.position.set(p.x+dz/l*(width/2+.25),this.height(w,p.x,p.z)+1.3,p.z-dx/l*(width/2+.25));tree.castShadow=true;this.group.add(tree)}}
}

junction(w,x,z,width,asphalt,curb,dirs){const half=width*.5,r=.45,shape=new THREE.Shape();shape.moveTo(-half+r,-half);shape.lineTo(half-r,-half);shape.quadraticCurveTo(half,-half,half,-half+r);shape.lineTo(half,half-r);shape.quadraticCurveTo(half,half,half-r,half);shape.lineTo(-half+r,half);shape.quadraticCurveTo(-half,half,-half,half-r);shape.lineTo(-half,-half+r);shape.quadraticCurveTo(-half,-half,-half+r,-half);const geo=new THREE.ShapeGeometry(shape,8);geo.rotateX(-Math.PI/2);const p=geo.attributes.position;for(let i=0;i<p.count;i++){const xx=x+p.getX(i),zz=z+p.getZ(i);p.setXYZ(i,xx,this.height(w,xx,zz)+.035,zz)}geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,asphalt);mesh.receiveShadow=true;this.group.add(mesh);for(let sx of [-1,1])for(let sz of [-1,1]){const points=[];for(let j=0;j<=12;j++){const a=j/12*Math.PI*.5;points.push({x:x+sx*(half-r+r*Math.cos(a)),z:z+sz*(half-r+r*Math.sin(a))})}this.ribbon(w,points,.055,0,curb,.075)}for(const d of dirs){this.line(w,[{x:x+d.x*1.25-d.z*.45,z:z+d.z*1.25+d.x*.45},{x:x+d.x*1.25+d.z*.45,z:z+d.z*1.25-d.x*.45}],.045,'#c7c5b6')}}
signal(x,y,z){const g=new THREE.Group();const p=new THREE.Mesh(new THREE.CylinderGeometry(.025,.04,2.1,8),this.v.mat('#555d58'));p.position.set(x,y+1.05,z);g.add(p);this.v.box(g,x,y+2,z,.14,.42,.11,'#3c4642');for(let i=0;i<3;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.035,6,6),this.v.mat(i===2?'#4ca56b':'#703f32'));m.position.set(x,y+1.86+i*.12,z+.065);g.add(m)}this.group.add(g)}
lamp(x,y,z,horizontal){const g=new THREE.Group();const pole=new THREE.Mesh(new THREE.CylinderGeometry(.025,.055,3,8),this.v.mat('#757d7c'));pole.position.set(x,y+1.5,z);g.add(pole);const arm=this.v.box(g,x+(horizontal?0:-.25),y+3,z+(horizontal?-.25:0),horizontal?.045:.6,.035,horizontal?.6:.045,'#7e8784');const bulb=new THREE.Mesh(new THREE.BoxGeometry(.13,.035,.31),new THREE.MeshStandardMaterial({color:'#e5e2ca',emissive:'#ffe2a0',emissiveIntensity:this.v.night?3:0,roughness:.3}));bulb.position.set(x+(horizontal?0:-.55),y+2.98,z+(horizontal?-.55:0));g.add(bulb);pole.castShadow=true;this.group.add(g);this.lamps.push(bulb)}
night(on){for(let b of this.lamps)b.material.emissiveIntensity=on?3:0}
}
